import{_ as o}from"./chunks/Audio.COine8Wh.js";import{_ as i}from"./chunks/Tags.BJ536pW3.js";import{c as a,o as s,j as r,G as t,ae as n,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes.","description":"","frontmatter":{"legisId":"2025-08-14-public-law-119-33","title":"To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes.","displayTitle":"S. 423, Public Law 119-33","lawNumber":"119-33","billNumber":"S. 423","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ33.xml","publishDate":"2025-08-14T00:00:00-05:00","industries":["healthcare","government-operations","labor"],"agencies":["Department of Veterans Affairs","Government Accountability Office"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes.\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-public-law-119-33\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes.\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-public-law-119-33\\",\\"datePublished\\":\\"2025-08-14T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-public-law-119-33\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-08-14-public-law-119-33.md","filePath":"congress-bills/2025-08-14-public-law-119-33.md","lastUpdated":1788887623000}'),p={name:"congress-bills/2025-08-14-public-law-119-33.md"},m=Object.assign(p,{setup(c){return(f,e)=>(s(),a("div",null,[e[0]||(e[0]=r("h1",{id:"to-protect-regular-order-for-budgeting-for-the-department-of-veterans-affairs-and-for-other-purposes",tabindex:"-1"},[l("To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes. "),r("a",{class:"header-anchor",href:"#to-protect-regular-order-for-budgeting-for-the-department-of-veterans-affairs-and-for-other-purposes","aria-label":'Permalink to "To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes."'},"​")],-1)),t(o),t(i,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Thursday, August 14, 2025. Public Law 119-33, S. 423.</p><p><strong>Headline:</strong> The law tightens oversight of Department of Veterans Affairs budget shortfalls, limits senior executive incentives, and creates a temporary office to improve service experiences.</p><p><strong>Why it matters:</strong> Congress will receive regular information about VA finances, executive incentive payments, and efforts to improve services for veterans and other beneficiaries.</p><p><strong>What the law does:</strong></p><ul><li>Requires the VA Secretary to brief designated House and Senate committees quarterly for three years on the department’s budget, funding shortfalls, and response plans.</li><li>Generally bars critical-skill incentives for senior executives at the VA Central Office and requires individual awards and specified approvals for other senior executives.</li><li>Requires annual reports to congressional veterans’ affairs committees on senior executives receiving critical-skill incentives.</li><li>Establishes a Veterans Experience Office reporting directly to the VA Secretary to coordinate customer-experience policy, gather feedback and usage data, review public information, and recommend improvements.</li><li>Requires the office to protect personal information, support annual reports to Congress, and close on September 30, 2028.</li><li>Directs the Comptroller General to independently review the VA’s customer-experience methods and results.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Veterans and other beneficiaries who use VA services.</li><li>VA senior executives, especially those based at the VA Central Office.</li><li>VA officials responsible for budgets, customer experience, data, and public-facing information.</li><li>Congressional committees overseeing veterans’ affairs and VA funding.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Veterans and beneficiaries may have more opportunities for their feedback and service-use data to inform VA improvements.</li><li>Personal information collected through customer-experience work must be protected.</li></ul><p><strong>Context:</strong> The Veterans Experience Office is temporary and ends on September 30, 2028.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="to-protect-regular-order-for-budgeting-for-the-department-of-veterans-affairs-and-for-other-purposes-1" tabindex="-1">To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes. <a class="header-anchor" href="#to-protect-regular-order-for-budgeting-for-the-department-of-veterans-affairs-and-for-other-purposes-1" aria-label="Permalink to &quot;To protect regular order for budgeting for the Department of Veterans Affairs, and for other purposes.&quot;">​</a></h3><p>This law increases congressional oversight of Department of Veterans Affairs budget shortfalls and restricts critical-skill incentive payments for senior VA employees. It also formally creates a temporary Veterans Experience Office to improve how veterans and other beneficiaries experience VA services, requires related reports, and directs an independent review of those efforts.</p><p><strong>Key takeaways:</strong></p><ul><li>For three years, the VA Secretary must brief designated House and Senate committees in person each quarter on the VA budget and any funding shortfall.</li><li>If the VA reports a shortfall, the Secretary must present plans to address or reduce it during the briefing.</li><li>Senior executives whose positions are at the VA Central Office generally cannot receive critical-skill incentives, while incentives for other senior executives must be awarded individually and receive specified approvals.</li><li>The VA must report annually to the congressional veterans’ affairs committees on senior executives who received critical-skill incentives.</li><li>The law establishes a Veterans Experience Office reporting directly to the VA Secretary to coordinate customer-experience policy, collect feedback and usage data, assess public-facing information, and recommend service improvements.</li><li>The Veterans Experience Office must support annual reporting to Congress, protect personal information, and end on September 30, 2028, while the Comptroller General must independently review the VA’s customer-experience methods and results.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ33.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ33.xml</a></p>',16))]))}});export{h as __pageData,m as default};
